/* ================= BASE STYLES & VARIABLES ================= */
html, body, #root, * {
  box-sizing: border-box;
  font-family: "Inter", system-ui, -apple-system, sans-serif !important;
}

html, body, #root {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background: #ffffff;
  overflow-x: hidden;
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  height: 6px;
  width: 6px;
}

::-webkit-scrollbar-track {
  background: #f1f5f9;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}

:root {
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --primary-border: #bfdbfe;
  --text-dark: #1f2937;
  --text-muted: #6b7280;
  --text-light: #9ca3af;
  --border-light: #e5e7eb;
  --border-focus: #3b82f6;
  --bg-surface: #f8fafc;
  --bg-card: #ffffff;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.05), 0 2px 4px -1px rgba(0,0,0,0.03);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.05), 0 4px 6px -2px rgba(0,0,0,0.03);
}

/* ================= LAYOUT CONTAINER ================= */
.viewport-container {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  width: 100vw;
  background: #ffffff;
  padding: 40px 20px;
}

.portal-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: 700px;
  text-align: center;
  animation: fadeIn 0.6s ease-out;
}

/* ================= TOP ICON ================= */
.top-icon-container {
  width: 72px;
  height: 72px;
  background-color: var(--primary-light);
  border: 1px solid var(--primary-border);
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  color: var(--primary);
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  box-shadow: var(--shadow-sm);
}

.top-icon-container:hover {
  transform: scale(1.05) rotate(2deg);
}

.top-icon-container svg {
  width: 32px;
  height: 32px;
}

/* ================= LABELS & HEADINGS ================= */
.app-label {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 12px;
}

.main-title {
  font-size: 52px;
  font-weight: 700;
  color: var(--text-dark);
  margin: 0 0 16px 0;
  line-height: 1.15;
  letter-spacing: -1px;
}

.main-desc {
  font-size: 18px;
  color: var(--text-muted);
  line-height: 1.7;
  max-width: 620px;
  margin: 0 0 40px 0;
}

.main-desc p {
  margin: 0 0 8px 0;
}

.main-desc p:last-child {
  margin-bottom: 0;
}

/* ================= BUYER PROFILE CARD ================= */
.profile-selection-card {
  width: 100%;
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: 12px;
  padding: 28px 24px;
  box-shadow: var(--shadow-md);
  text-align: left;
  margin-bottom: 32px;
  transition: box-shadow 0.3s;
}

.profile-selection-card:focus-within {
  box-shadow: var(--shadow-lg);
}

.card-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-dark);
  margin: 0 0 16px 0;
}

/* ================= SEARCHABLE DROPDOWN ================= */
.dropdown-wrapper {
  position: relative;
  width: 100%;
}

/* Trigger Button style */
.dropdown-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 12px 16px;
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: 8px;
  cursor: pointer;
  outline: none;
  font-size: 14px;
  transition: all 0.2s;
  min-height: 52px;
}

.dropdown-trigger:hover {
  border-color: #cbd5e1;
  background: var(--bg-surface);
}

.dropdown-trigger.open {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.dropdown-trigger-content {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-grow: 1;
}

.selected-profile-info {
  display: flex;
  flex-direction: column;
  text-align: left;
}

.selected-profile-name {
  font-weight: 600;
  color: var(--text-dark);
}

.selected-profile-meta {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 2px;
}

.dropdown-placeholder {
  color: var(--text-light);
}

.chevron-icon {
  color: var(--text-muted);
  transition: transform 0.2s;
}

.chevron-icon.rotated {
  transform: rotate(180deg);
}

/* Dropdown Menu Popover */
.dropdown-menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  width: 100%;
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: 8px;
  box-shadow: var(--shadow-lg);
  z-index: 50;
  overflow: hidden;
  animation: slideDown 0.18s cubic-bezier(0, 0, 0.2, 1);
}

/* Search input container inside menu */
.dropdown-search-container {
  display: flex;
  align-items: center;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-surface);
  position: sticky;
  top: 0;
  z-index: 10;
}

.search-input-icon {
  color: var(--text-light);
  margin-right: 10px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
}

.dropdown-search-input {
  width: 100%;
  border: none;
  background: transparent;
  outline: none;
  font-size: 14px;
  color: var(--text-dark);
  padding: 4px 0;
}

.dropdown-search-input::placeholder {
  color: var(--text-light);
}

.clear-search-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 2px;
  margin-left: 6px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}

.clear-search-btn:hover {
  background: #e2e8f0;
  color: var(--text-dark);
}

/* Scrollable items list */
.dropdown-list {
  max-height: 280px;
  overflow-y: auto;
  padding: 6px 0;
  margin: 0;
  list-style: none;
}

.dropdown-item {
  display: flex;
  align-items: center;
  padding: 10px 16px;
  cursor: pointer;
  transition: background-color 0.15s, color 0.15s;
}

.dropdown-item:hover, .dropdown-item.highlighted {
  background-color: var(--bg-surface);
}

.dropdown-item.selected {
  background-color: var(--primary-light);
}

.dropdown-item-details {
  display: flex;
  flex-direction: column;
  margin-left: 12px;
  flex-grow: 1;
}

.item-name-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.item-name {
  font-weight: 600;
  font-size: 14px;
  color: var(--text-dark);
}

.item-status-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.item-status-active {
  background: #ecfdf5;
  color: #059669;
  border: 1px solid #a7f3d0;
}

.item-status-away {
  background: #fffbeb;
  color: #d97706;
  border: 1px solid #fde68a;
}

.item-role {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 1px;
}

.item-dept-bu {
  font-size: 11px;
  color: var(--text-light);
  margin-top: 2px;
}

/* ================= AVATAR STYLE ================= */
.avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background-color: #cbd5e1;
  color: #475569;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
  flex-shrink: 0;
  border: 1.5px solid #ffffff;
  box-shadow: var(--shadow-sm);
}

/* Colorful Avatars for Enterprise feel */
.avatar-bg-0 {
  background-color: #dbeafe;
  color: #1e40af;
}

.avatar-bg-1 {
  background-color: #fce7f3;
  color: #9d174d;
}

.avatar-bg-2 {
  background-color: #e0f2fe;
  color: #0369a1;
}

.avatar-bg-3 {
  background-color: #d1fae5;
  color: #065f46;
}

.avatar-bg-4 {
  background-color: #fef3c7;
  color: #92400e;
}

/* ================= ACTIONS ================= */
.actions-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  margin-bottom: 48px;
  width: 100%;
}

.btn-primary {
  width: 220px;
  height: 48px;
  background-color: var(--primary);
  color: #ffffff;
  border: none;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  box-shadow: 0 2px 4px rgba(37, 99, 235, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.btn-primary:hover:not(:disabled) {
  background-color: var(--primary-hover);
  box-shadow: 0 4px 8px rgba(37, 99, 235, 0.25);
  transform: translateY(-1px);
}

.btn-primary:active:not(:disabled) {
  transform: translateY(0);
}

.btn-primary:disabled {
  background-color: #cbd5e1;
  color: #94a3b8;
  cursor: not-allowed;
  box-shadow: none;
}

.btn-secondary {
  background: none;
  border: none;
  color: var(--primary);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 4px;
  transition: background 0.15s, color 0.15s;
}

.btn-secondary:hover {
  background: var(--primary-light);
  color: var(--primary-hover);
}

/* ================= FEATURE HIGHLIGHTS ================= */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  width: 100%;
  border-top: 1px solid var(--border-light);
  padding-top: 40px;
  margin-bottom: 40px;
  text-align: left;
}

.feature-item {
  display: flex;
  gap: 14px;
  animation: fadeInUp 0.5s ease-out both;
}

.feature-item:nth-child(1) {
  animation-delay: 0.1s;
}

.feature-item:nth-child(2) {
  animation-delay: 0.2s;
}

.feature-item:nth-child(3) {
  animation-delay: 0.3s;
}

.feature-icon-wrapper {
  color: var(--primary);
  background-color: var(--primary-light);
  border-radius: 10px;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid var(--primary-border);
}

.feature-icon-wrapper svg {
  width: 20px;
  height: 20px;
}

.feature-content {
  display: flex;
  flex-direction: column;
}

.feature-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-dark);
  margin: 0 0 4px 0;
}

.feature-desc {
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.5;
  margin: 0;
}

/* ================= FOOTER ================= */
.portal-footer {
  font-size: 11px;
  color: var(--text-light);
  letter-spacing: 0.5px;
  line-height: 1.8;
  width: 100%;
  border-top: 1px solid var(--border-light);
  padding-top: 24px;
  margin-top: auto;
}

.footer-row {
  display: flex;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
}

.footer-bullet {
  color: var(--text-light);
}

/* ================= LOADING & EMPTY STATES ================= */
.loading-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px 0;
  color: var(--text-muted);
  font-size: 14px;
  gap: 12px;
}

.spinner {
  width: 28px;
  height: 28px;
  border: 3px solid #f3f4f6;
  border-top: 3px solid var(--primary);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

.empty-dropdown-state {
  padding: 24px;
  text-align: center;
  color: var(--text-muted);
  font-size: 13px;
}

.empty-state-icon {
  margin-bottom: 8px;
  color: var(--text-light);
}

/* ================= ANIMATIONS ================= */
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes spin {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
/* ================= RESPONSIVENESS ================= */
@media (max-width: 768px) {
  .main-title {
    font-size: 40px;
  }
  .features-grid {
    grid-template-columns: 1fr;
    gap: 20px;
    padding-top: 28px;
  }
  .feature-item {
    gap: 12px;
  }
}
@media (max-width: 480px) {
  .viewport-container {
    padding: 20px 12px;
  }
  .main-title {
    font-size: 32px;
  }
  .main-desc {
    font-size: 15px;
    margin-bottom: 28px;
  }
  .profile-selection-card {
    padding: 20px 16px;
  }
  .btn-primary {
    width: 100%;
  }
}

