// ================= MOCK DATA (Fallback) =================
// Helper to find the buyer profiles array dynamically from any model parameter
const findProfilesInModel = model => {
  if (!model) return null;
  if (Array.isArray(model)) return model;
  if (Array.isArray(model.buyerProfiles)) return model.buyerProfiles;
  if (Array.isArray(model.buyers)) return model.buyers;
  if (Array.isArray(model.data)) return model.data;
  if (Array.isArray(model.list)) return model.list;

  // Fallback: search for the first property that is an array
  for (const key in model) {
    if (Object.prototype.hasOwnProperty.call(model, key) && Array.isArray(model[key])) {
      return model[key];
    }
  }
  return null;
};

// Helper to normalize profiles data coming from Appsmith model
const normalizeProfiles = incoming => {
  if (!Array.isArray(incoming)) return [];
  return incoming.map(p => {
    const buyerId = String(p.BuyerID ?? p.buyerId ?? p.buyer_id ?? p.id ?? '').trim();
    const name = String(p.BuyerName ?? p.name ?? p.buyerName ?? p.buyer_name ?? '').trim();
    const email = String(p.BuyerEmailID ?? p.buyerEmailID ?? p.buyerEmailId ?? p.email ?? '').trim();

    // Calculate initials avatar from name if not provided
    let avatar = p.avatar || '';
    if (!avatar && name) {
      const parts = name.split(/\s+/);
      if (parts.length >= 2) {
        avatar = (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
      } else {
        avatar = name.slice(0, 2).toUpperCase();
      }
    }
    return {
      buyerId,
      name,
      email,
      avatar: avatar || 'BY',
      raw: p
    };
  });
};

