    <line x1="9" y1="9" x2="15" y2="15" />
  </svg>
);

// ================= MOCK DATA (Fallback) =================
// Helper to find the buyer profiles array dynamically from any model parameter
const findProfilesInModel = (model) => {
  if (!model) return null;
  if (Array.isArray(model)) return model;
  if (Array.isArray(model.buyerProfiles)) return model.buyerProfiles;
  if (Array.isArray(model.buyers)) return model.buyers;
  if (Array.isArray(model.data)) return model.data;
  if (Array.isArray(model.list)) return model.list;

  // Fallback: search for the first property that is an array
  for (const key in model) {
    if (Object.prototype.hasOwnProperty.call(model, key) && Array.isArray(model[key])) {
      return model[key];
    }
  }
  return null;
};

// Helper to normalize profiles data coming from Appsmith model
const normalizeProfiles = (incoming) => {
  if (!Array.isArray(incoming)) return [];
  return incoming.map(p => {
    const buyerId = String(p.BuyerID ?? p.buyerId ?? p.buyer_id ?? p.id ?? '').trim();
    const name = String(p.BuyerName ?? p.name ?? p.buyerName ?? p.buyer_name ?? '').trim();
    const email = String(p.BuyerEmailID ?? p.buyerEmailID ?? p.buyerEmailId ?? p.email ?? '').trim();

    // Calculate initials avatar from name if not provided
    let avatar = p.avatar || '';
    if (!avatar && name) {
      const parts = name.split(/\s+/);
      if (parts.length >= 2) {
        avatar = (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
      } else {
        avatar = name.slice(0, 2).toUpperCase();
      }
    }

    return {
      buyerId,
      name,
      email,
      avatar: avatar || 'BY',
      raw: p
    };
  });
};

// ================= MAIN COMPONENT =================
function LandingPage() {
  const [profiles, setProfiles] = useState([]);
  const [isLoading, setIsLoading] = useState(false);

  // Interaction State
  const [selectedProfile, setSelectedProfile] = useState(null);
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [activeIndex, setActiveIndex] = useState(-1);

  // Refs
  const dropdownRef = useRef(null);
  const searchInputRef = useRef(null);
  const itemsRef = useRef([]);

  // Sync with Appsmith Model
  useEffect(() => {
    if (typeof appsmith !== 'undefined') {
      const handleModelChange = (model) => {
        if (model) {
          const foundArray = findProfilesInModel(model);
          const modelLoading = model.isLoading === true;

          if (foundArray) {
            setProfiles(normalizeProfiles(foundArray));
          } else {
            setProfiles([]);
          }
          setIsLoading(modelLoading);
        }
      };

      appsmith.onModelChange(handleModelChange);

      if (appsmith.model) {
        handleModelChange(appsmith.model);
      }
    } else {
      // Local/Standalone Testing Fallback
      setProfiles([]);
      setIsLoading(false);
    }
  }, []);

  // Sync selection back to Appsmith model on change
  useEffect(() => {
    if (typeof appsmith !== 'undefined' && appsmith.updateModel) {
      if (selectedProfile) {
        appsmith.updateModel({
          selectedBuyer: selectedProfile,
          selectedBuyerId: selectedProfile.buyerId,
          selectedBuyerName: selectedProfile.name,
          selectedBuyerEmail: selectedProfile.email
        });
      } else {
        appsmith.updateModel({
          selectedBuyer: null,
          selectedBuyerId: null,
          selectedBuyerName: null,
          selectedBuyerEmail: null
        });
      }
    }
  }, [selectedProfile]);

  // Click Outside Listener to close dropdown
  useEffect(() => {
    function handleClickOutside(event) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Focus search input when dropdown opens
  useEffect(() => {
    if (isOpen && searchInputRef.current) {
      searchInputRef.current.focus();
      setActiveIndex(-1);
    }
  }, [isOpen]);

  // Filter profiles based on search query (by name, ID, or email)
  const filteredProfiles = useMemo(() => {
    const query = searchTerm.toLowerCase().trim();
    if (!query) return profiles;
    return profiles.filter(
      p =>
        p.name?.toLowerCase().includes(query) ||
        p.buyerId?.toLowerCase().includes(query) ||
        p.email?.toLowerCase().includes(query)
    );
  }, [profiles, searchTerm]);

  // Keyboard navigation logic
  const handleKeyDown = (e) => {
    if (!isOpen) {
      if (e.key === "Enter" || e.key === "ArrowDown" || e.key === " ") {
        e.preventDefault();
        setIsOpen(true);
      }
      return;
    }

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        setActiveIndex((prevIndex) => {
          const nextIndex = prevIndex + 1 >= filteredProfiles.length ? 0 : prevIndex + 1;
          scrollIntoView(nextIndex);
          return nextIndex;
        });
        break;
      case "ArrowUp":
        e.preventDefault();
        setActiveIndex((prevIndex) => {
          const nextIndex = prevIndex - 1 < 0 ? filteredProfiles.length - 1 : prevIndex - 1;
          scrollIntoView(nextIndex);
          return nextIndex;
        });
        break;
      case "Enter":
        e.preventDefault();
        if (activeIndex >= 0 && activeIndex < filteredProfiles.length) {
          selectProfile(filteredProfiles[activeIndex]);
        }
        break;
      case "Escape":
      case "Tab":
        setIsOpen(false);
        break;
      default:
        break;
    }
  };

  const scrollIntoView = (index) => {
    if (itemsRef.current[index]) {
      itemsRef.current[index].scrollIntoView({
        block: "nearest",
        behavior: "smooth"
      });
    }
  };

  const selectProfile = (profile) => {
    setSelectedProfile(profile);
    setIsOpen(false);
    setSearchTerm("");
    setActiveIndex(-1);
  };

  const handleContinue = () => {
    if (selectedProfile) {
      if (typeof appsmith !== 'undefined') {
        // Update model with the selection
        if (appsmith.updateModel) {
          appsmith.updateModel({
            selectedBuyer: selectedProfile,
            selectedBuyerId: selectedProfile.buyerId,
            selectedBuyerName: selectedProfile.name,
            selectedBuyerEmail: selectedProfile.email
          });
        }
        // Trigger onEnterDashboard event with specific payload
        if (appsmith.triggerEvent) {
          appsmith.triggerEvent('onEnterDashboard', { 
            buyerId: selectedProfile.buyerId, 
            buyerName: selectedProfile.name,
            buyerEmail: selectedProfile.email 
          });
        }
      } else {
        alert(`Proceeding to Dashboard as: ${selectedProfile.name} (ID: ${selectedProfile.buyerId})`);
      }
    }
  };

  const handleHelp = () => {
    if (typeof appsmith !== 'undefined' && appsmith.triggerEvent) {
      appsmith.triggerEvent('onHelp');
    } else {
      alert("Help clicked. Opening system support ticket portal.");
    }
  };

  const getAvatarInitials = (name) => {
    if (!name) return "BU";
    const parts = name.split(" ");
    if (parts.length >= 2) {
      return (parts[0][0] + parts[1][0]).toUpperCase();
    }
    return name.slice(0, 2).toUpperCase();
  };

  // Render Loader Skeletons for Selection Box
  const renderLoadingSkeleton = () => (
    <div className="profile-selection-card">
      <div className="card-title">Select Buyer Profile</div>
      <div className="loading-wrapper">
        <div className="spinner"></div>
        <span>Syncing Buyer Profiles from Enterprise directory...</span>
      </div>
    </div>
  );

  return (
    <div className="viewport-container">
      <div className="portal-container">

        {/* Top Icon */}
        <div className="top-icon-container" title="Smart Procure Portal">
          <SourcingIcon />
        </div>

        {/* Application Label */}
        <div className="app-label">Global Procurement Operations</div>

        {/* Welcome Title */}
        <h1 className="main-title">Smart Procure Portal</h1>

        {/* Description */}
        <div className="main-desc">
          <p>Access the enterprise procurement sourcing network.</p>
          <p>Choose your buyer account profile to enter your personalized procurement dashboard.</p>
        </div>

        {/* Buyer Profile Selection Box */}
        {isLoading ? (
          renderLoadingSkeleton()
        ) : (
          <div className="profile-selection-card">
            <div className="card-title">Select Buyer Profile</div>

            <div className="dropdown-wrapper" ref={dropdownRef}>

              {/* Trigger Button */}
              <button
                className={`dropdown-trigger ${isOpen ? 'open' : ''}`}
                onClick={() => setIsOpen(!isOpen)}
                onKeyDown={handleKeyDown}
                aria-haspopup="listbox"
                aria-expanded={isOpen}
                type="button"
              >
                <div className="dropdown-trigger-content">
                  {selectedProfile ? (
                    <>
                      <div className={`avatar avatar-bg-${profiles.indexOf(selectedProfile) % 5}`}>
                        {selectedProfile.avatar || getAvatarInitials(selectedProfile.name)}
                      </div>
                      <div className="selected-profile-info">
                        <span className="selected-profile-name">{selectedProfile.name}</span>
                        <span className="selected-profile-meta">
                          Buyer ID: {selectedProfile.buyerId}{selectedProfile.email ? ` • ${selectedProfile.email}` : ''}
                        </span>
                      </div>
                    </>
                  ) : (
                    <span className="dropdown-placeholder">Search or Select Buyer</span>
                  )}
                </div>
                <ChevronIcon className={`chevron-icon ${isOpen ? 'rotated' : ''}`} />
              </button>

              {/* Menu Popover */}
              {isOpen && (
                <div className="dropdown-menu" role="listbox">
                  {/* Search Input Box */}
                  <div className="dropdown-search-container">
                    <span className="search-input-icon">
                      <SearchIcon />
                    </span>
                    <input
                      ref={searchInputRef}
                      type="text"
                      className="dropdown-search-input"
                      placeholder="Search by name, buyer ID, or email..."
                      value={searchTerm}
                      onChange={(e) => {
                        setSearchTerm(e.target.value);
                        setActiveIndex(-1);
                      }}
                      onKeyDown={handleKeyDown}
                    />
                    {searchTerm && (
                      <button
                        className="clear-search-btn"
                        onClick={() => {
                          setSearchTerm("");
                          if (searchInputRef.current) searchInputRef.current.focus();
                        }}
                        type="button"
                        title="Clear Search"
                      >
                        <XIcon />
                      </button>
                    )}
                  </div>

                  {/* Options List */}
                  {filteredProfiles.length > 0 ? (
                    <ul className="dropdown-list">
                      {filteredProfiles.map((p, idx) => {
                        const isSelected = selectedProfile?.buyerId === p.buyerId;
                        const isHighlighted = activeIndex === idx;
                        const originalIndex = profiles.indexOf(p);

                        return (
                          <li
                            key={p.buyerId || idx}
                            ref={el => itemsRef.current[idx] = el}
                            className={`dropdown-item ${isSelected ? 'selected' : ''} ${isHighlighted ? 'highlighted' : ''}`}
                            onClick={() => selectProfile(p)}
                            onMouseEnter={() => setActiveIndex(idx)}
                            role="option"
                            aria-selected={isSelected}
                          >
                            <div className={`avatar avatar-bg-${originalIndex % 5}`}>
                              {p.avatar || getAvatarInitials(p.name)}
                            </div>

                            <div className="dropdown-item-details">
                              <div className="item-name-row">
                                <span className="item-name">{p.name}</span>
                                {p.status && (
                                  <span className={`item-status-badge ${p.status === 'active' ? 'item-status-active' : 'item-status-away'}`}>
                                    {p.status}
                                  </span>
                                )}
                              </div>
                              <span className="item-role">Buyer ID: {p.buyerId}</span>
                              {p.email && <span className="item-dept-bu">{p.email}</span>}
                            </div>
                          </li>
                        );
                      })}
                    </ul>
                  ) : (
                    <div className="empty-dropdown-state">
                      <EmptyStateIcon />
                      <div>
                        {searchTerm 
                          ? `No buyer profiles found matching "${searchTerm}"`
                          : "No buyer profiles available. Please ask support team to create your profile."
                        }
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="actions-container">
          <button
            className="btn-primary"
            disabled={!selectedProfile || isLoading}
            onClick={handleContinue}
            type="button"
          >
            Continue to Dashboard
          </button>

          <button
            className="btn-secondary"
            onClick={handleHelp}
            type="button"
          >
            Need help selecting a profile?
          </button>
        </div>

        {/* Feature Highlights */}
        <div className="features-grid">

          <div className="feature-item">
            <div className="feature-icon-wrapper">
              <DashboardIcon />
            </div>
            <div className="feature-content">
              <h3 className="feature-title">Procurement Dashboard</h3>
              <p className="feature-desc">Monitor purchase requisitions and outline agreements in real time.</p>
            </div>
          </div>

          <div className="feature-item">
            <div className="feature-icon-wrapper">
              <RobotIcon />
            </div>
            <div className="feature-content">
              <h3 className="feature-title">AI Assisted Vendor Selection</h3>
              <p className="feature-desc">Receive intelligent vendor recommendations based on historical performance.</p>
            </div>
          </div>

          <div className="feature-item">
            <div className="feature-icon-wrapper">
              <ComplianceIcon />
            </div>
            <div className="feature-content">
              <h3 className="feature-title">Contract Compliance</h3>
              <p className="feature-desc">Validate OA and ARC rate contracts sequentially before dispatching suppliers.</p>
            </div>
          </div>

        </div>

        {/* Footer */}
        <footer className="portal-footer">
          <div className="footer-row">
            <span>Version 2.4.1</span>
            <span className="footer-bullet">&bull;</span>
            <span>Production Environment</span>
            <span className="footer-bullet">&bull;</span>
            <span>&copy; 2026 Apex Enterprise Group</span>
          </div>
        </footer>

      </div>
    </div>
  );
}

// Render component inside Appsmith custom root container
appsmith.onReady(() => {
  const container = document.getElementById('root');
  if (container) {
    container.innerHTML = '';
    ReactDOM.render(<LandingPage />, container);
  }
});
